interface NoteSummary {
  id: string;
  title: string;
  createdAt: string;
  updatedAt: string;
  taskTotal: number;
  taskCompleted: number;
}

interface Note extends NoteSummary {
  body: unknown;
}

const NOT_FOUND_MESSAGE = "This note could not be found.";
const DEFAULT_BODY = { type: "doc", content: [{ type: "paragraph" }] };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function countTasks(body: unknown): {
  total: number;
  completed: number;
} {
  let total = 0;
  let completed = 0;
  const visit = (node: unknown): void => {
    if (!isRecord(node)) {
      return;
    }
    if (node.type === "taskItem") {
      total += 1;
      if (isRecord(node.attrs) && node.attrs.checked === true) {
        completed += 1;
      }
    }
    if (Array.isArray(node.content)) {
      for (const child of node.content) {
        visit(child);
      }
    }
  };
  visit(body);
  return { total, completed };
}

function toSummary(row: NoteRow): NoteSummary {
  return {
    id: row.id,
    title: row.title,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    taskTotal: row.taskTotal,
    taskCompleted: row.taskCompleted,
  };
}

function toNote(row: NoteRow): Note {
  return { ...toSummary(row), body: JSON.parse(row.body) as unknown };
}

