import express from "express";
import type { ErrorRequestHandler, Express } from "express";
import { authRouter, requireUser } from "./auth.js";
import type { Db } from "./db.js";
import { notesRouter } from "./routes/notes.js";

function errorType(err: unknown): string | undefined {
  if (typeof err === "object" && err !== null && "type" in err) {
    const type = (err as { type: unknown }).type;
    return typeof type === "string" ? type : undefined;
  }
  return undefined;
}

const errorHandler: ErrorRequestHandler = (err: unknown, _req, res, next) => {
  if (res.headersSent) {
    next(err);
    return;
  }
  const type = errorType(err);
  if (type === "entity.parse.failed") {
    res.status(400).json({ message: "The request body could not be read." });
    return;
  }
  if (type === "entity.too.large") {
    res.status(413).json({ message: "This note is too large to save." });
    return;
  }
  console.error(err);
  res.status(500).json({
    message: "Something went wrong on our side. Please try again.",
  });
};

export function createApp(db: Db): Express {
  const app = express();
  app.use(express.json({ limit: "1mb" }));

  app.get("/api/health", (_req, res) => {
    res.json({ status: "ok" });
  });

  app.use("/api/auth", authRouter(db));
  app.use("/api/notes", requireUser(db), notesRouter(db));

  app.use(errorHandler);
  return app;
}

import { config } from "./config.js";
import { openDatabase } from "./db.js";
import { createApp } from "./app.js";

const db = openDatabase(config.dataDir);
const app = createApp(db);

app.listen(config.port, () => {
  console.log(`crew-chatter backend listening on ${config.port}`);
});

