export function asString(value: SQLOutputValue): string {
  if (typeof value !== "string") {
    throw new Error("Expected a string column value");
  }
  return value;
}

export function asNumber(value: SQLOutputValue): number {
  if (typeof value === "number") {
    return value;
  }
  if (typeof value === "bigint") {
    return Number(value);
  }
  throw new Error("Expected a numeric column value");
}

export function asNullableString(value: SQLOutputValue): string | null {
  if (value === null) {
    return null;
  }
  return asString(value);
}

